```scss
// function to compute modular exponentiation (base^exp mod modulus)
function modExp(base, exp, modulus) {
  if (exp == 0) return 1;
  if (exp % 2 == 0) return modExp((base * base) % modulus, exp / 2, modulus);
  return (base * modExp(base, exp - 1, modulus)) % modulus;
}

// function to compute the greatest common divisor of two numbers
function gcd(a, b) {
  if (b == 0) return a;
  return gcd(b, a % b);
}

// function to compute the modular multiplicative inverse of a modulo m
function modInverse(a, m) {
  for (let x = 1; x < m; x++) {
    if ((a * x) % m == 1) return x;
  }
  return null;
}

// function to generate a public-private key pair
function generateKeys(p, q) {
  let n = p * q;
  let phi = (p - 1) * (q - 1);
  let e = 2;
  while (gcd(e, phi) != 1) e++;
  let d = modInverse(e, phi);
  return { public: [e, n], private: [d, n] };
}

// function to encrypt a message using the public key
function encrypt(message, publicKey) {
  let m = BigInt("0x" + Buffer.from(message, 'ascii').toString('hex'));
  let e = BigInt(publicKey[0]);
  let n = BigInt(publicKey[1]);
  let c = modExp(m, e, n);
  return c.toString();
}

// function to decrypt a message using the private key
function decrypt(ciphertext, privateKey) {
  let c = BigInt(ciphertext);
  let d = BigInt(privateKey[0]);
  let n = BigInt(privateKey[1]);
  let m = modExp(c, d, n);
  let hexString = m.toString(16);
  let hexBuffer = Buffer.from(hexString, 'hex');
  let message = hexBuffer.toString('ascii');
  return message;
}

// example usage
let p = 23;
let q = 37;
let keys = generateKeys(p, q);
let publicKey = keys.public;
let privateKey = keys.private;
let message = "Hello, world!";
let ciphertext = encrypt(message, publicKey);
let plaintext = decrypt(ciphertext, privateKey);
console.log("Original message: " + message);
console.log("Ciphertext: " + ciphertext);
console.log("Decrypted message: " + plaintext);
```
