```rust
use bitcoin::network::constants::Network;
use bitcoin::util::key::PrivateKey;
use bitcoin::Address;
use secp256k1::Secp256k1;
use shamirsecretsharing::{Share, SharedSecret};
use std::env;
use tokio::net::{TcpListener, TcpStream};
use tokio_tungstenite::{accept_async, connect_async, WebSocketStream};
use tungstenite::protocol::Message;

#[tokio::main]
async fn main() {
    let args: Vec<String> = env::args().collect();
    if args.len() < 2 {
        panic!("Provide instance ID (1, 2, or 3)");
    }
    let instance_id: u32 = args[1].parse().expect("Instance ID should be a number");

    let secp = Secp256k1::new();
    let (private_key, public_key) = secp.generate_keypair(&mut rand::thread_rng());
    let private_key = PrivateKey {
        compressed: true,
        network: Network::Bitcoin,
        key: private_key,
    };
    let address = Address::p2pkh(&public_key, Network::Bitcoin);

    println!("Bitcoin address: {}", address);
    println!("Private key: {}", private_key);

    let secret = SharedSecret::new(&private_key.to_bytes(), 2, 3);
    let shares: Vec<Share> = secret.split().unwrap();

    match instance_id {
        1 => {
            let listener = TcpListener::bind("127.0.0.1:8080").await.unwrap();
            let mut received_shares = Vec::new();

            while let Ok((stream, _)) = listener.accept().await {
                let mut ws_stream = accept_async(stream).await.unwrap();
                if let Ok(msg) = ws_stream.read_message().await {
                    if let Message::Text(share_str) = msg {
                        received_shares.push(Share::deserialize(&share_str).unwrap());
                        if received_shares.len() >= 2 {
                            let reconstructed_secret = SharedSecret::reconstruct(&received_shares).unwrap();
                            let reconstructed_private_key = PrivateKey::from_wif(&reconstructed_secret.serialize()).unwrap();
                            let reconstructed_address = Address::p2pkh(&reconstructed_private_key.public_key(&secp), Network::Bitcoin);
                            println!("Reconstructed Bitcoin address: {}", reconstructed_address);
                            break;
                        }
                    }
                }
            }
        }
        2 | 3 => {
            let url = format!("ws://127.0.0.1:8080");
            let (mut ws_stream, _) = connect_async(url).await.unwrap();
            let share_str = shares[(instance_id - 1) as usize].serialize();
            ws_stream.write_message(Message::text(share_str)).await.unwrap();
        }
        _ => panic
