Here is an example of a C# application that loops through all Star Wars characters and checks to see if there are any Facebook users with the same name:
```
using System;
using System.Collections.Generic;
using System.Net;
using System.Net.Http;
using System.Text;
using Newtonsoft.Json.Linq;

namespace FacebookAndStarWars
{
    class Program
    {
        static void Main(string[] args)
        {
            // Set up the HTTP clients and requests
            var starWarsClient = new HttpClient();
            var starWarsRequest = new HttpRequestMessage
            {
                Method = HttpMethod.Get,
                RequestUri = new Uri("https://swapi.dev/api/people/"),
            };
            var facebookClient = new HttpClient();
            var facebookRequest = new HttpRequestMessage
            {
                Method = HttpMethod.Get,
                RequestUri = new Uri("https://graph.facebook.com/v8.0/me?fields=friends{name}"),
            };

            // Add the access token to the Facebook request
            facebookRequest.Headers.Authorization = new AuthenticationHeaderValue("Bearer", ACCESS_TOKEN);

            // Send the requests and handle the responses
            var starWarsResponse = await starWarsClient.SendAsync(starWarsRequest);
            var facebookResponse = await facebookClient.SendAsync(facebookRequest);
            if (starWarsResponse.IsSuccessStatusCode && facebookResponse.IsSuccessStatusCode)
            {
                var starWarsContent = await starWarsResponse.Content.ReadAsStringAsync();
                var starWarsJson = JObject.Parse(starWarsContent);
                var starWarsCharacters = starWarsJson["results"].ToObject<List<Character>>();

                var facebookContent = await facebookResponse.Content.ReadAsStringAsync();
                var facebookJson = JObject.Parse(facebookContent);
                var facebookFriends = facebookJson["friends"]["data"].ToObject<List<Friend>>();

                // Loop through the Star Wars characters and compare their names to the Facebook friends
                foreach (var character in starWarsCharacters)
                {
                    var matchingFriend = facebookFriends.Find(f => f.Name == character.Name);
                    if (matchingFriend != null)
                    {
                        Console.WriteLine(character.Name + " is also a Facebook friend!");
                    }
                }
            }
            else
            {
                Console.WriteLine("Error: " + starWarsResponse.StatusCode + ", " + facebookResponse.StatusCode);
            }
        }
    }

    // Helper classes to deserialize the JSON responses from the APIs
    public class Character
    {
        public string Name { get; set; }
    }

    public class Friend
    {
        public string Name { get; set; }
    }
}
```
