Here's the reworked `VerifyToken` class using `jose` instead of `pyjwt`:
```python
import json
from urllib.request import urlopen

from jose import jwt, jwks
class VerifyToken:
    """Does all the token verification using JOSE"""

    def __init__(self, token):
        self.token = token

        self.jwks_url = f'https://{self.config["DOMAIN"]}/.well-known/jwks.json'
        self.jwks = json.loads(urlopen(self.jwks_url).read())
        self.keys = {}

        for key in self.jwks["keys"]:
            kid = key["kid"]
            kty = key["kty"]
            alg = key["alg"]
            if alg == "RS256" and kty == "RSA":
                self.keys[kid] = jwt.RSAKey(
                    kid=kid,
                    key=key["n"],
                    e=key["e"],
                    alg=alg,
                )

    def verify(self):
        # This gets the 'kid' from the passed token
        try:
            header = jwt.get_unverified_header(self.token)
        except jwt.JWTError as error:
            return {"status": "error", "msg": error.__str__()}

        if "kid" not in header:
            return {"status": "error", "msg": "Authorization malformed."}

        try:
            key = self.keys[header["kid"]]
        except KeyError:
            return {"status": "error", "msg": "Unable to find appropriate key."}

        try:
            payload = jwt.decode(
                self.token,
                key,
                algorithms=self.config["ALGORITHMS"],
                audience=self.config["API_AUDIENCE"],
                issuer=self.config["ISSUER"],
            )
        except jwt.ExpiredSignatureError:
            return {"status": "error", "msg": "Token expired."}
        except jwt.JWTClaimsError:
            return {
                "status": "error",
                "msg": "Incorrect claims. Please check the audience and issuer.",
            }
        except Exception as e:
            return {"status": "error", "msg": str(e)}

        return payload
```
Note that this code requires `jose` library to be installed (`pip install python-jose`). The `VerifyToken` class now uses `urlopen` to fetch the JWKS JSON file, and then iterates over the keys in the `jwks` object to build a dictionary of `jose.jwt.RSAKey` instances. The `verify` method then decodes the token using the appropriate key found by its `kid`.

