#include <iostream>
#include <vector>

using namespace std;

void simulateSIR(double beta, double gamma, int S, int I, int R, int duration) {
    vector<int> S_vec, I_vec, R_vec; // vectors to store population at each time step
    S_vec.push_back(S);
    I_vec.push_back(I);
    R_vec.push_back(R);

    for (int i = 0; i < duration; i++) {
        int new_I = beta * S_vec[i] * I_vec[i]; // calculate new infections
        int new_R = gamma * I_vec[i]; // calculate new recoveries

        int S_next = S_vec[i] - new_I; // update susceptible population
        int I_next = I_vec[i] + new_I - new_R; // update infected population
        int R_next = R_vec[i] + new_R; // update recovered population

        S_vec.push_back(S_next);
        I_vec.push_back(I_next);
        R_vec.push_back(R_next);
    }

    // print population at each time step
    for (int i = 0; i < S_vec.size(); i++) {
        cout << "Day " << i << ": S = " << S_vec[i] << ", I = " << I_vec[i] << ", R = " << R_vec[i] << endl;
    }
}

int main() {
    double beta, gamma;
    int S, I, R, duration;

