    cin >> beta;
    cout << "Enter gamma: ";
    cin >> gamma;
    cout << "Enter initial susceptible population: ";
    cin >> S;
    cout << "Enter initial infected population: ";
    cin >> I;
    cout << "Enter initial recovered population: ";
    cin >> R;
    cout << "Enter duration (in days): ";
    cin >> duration;

    simulateSIR(beta, gamma, S, I, R, duration);

    return 0;
}
```
