To set up authentication for your GraphQL server, you can follow these steps:

1. Update the REST API data source to pass the token in the `Authorization` header:
```javascript
// src/dataProvider.js
import { RESTDataSource } from 'apollo-datasource-rest';

class JobsAPI extends RESTDataSource {
  constructor() {
    super();
    this.baseURL = 'http://quickshyft.co.za/api/v1/';
  }

  // Add this method to set the token in the Authorization header
  willSendRequest(request) {
    if (this.context.token) {
      request.headers.set('Authorization', `Bearer ${this.context.token}`);
    }
  }

  // ...rest of the code
}

export default JobsAPI;
```
1. Update the `src/graphql/resolvers/jobResolvers.js` file to check for authentication before calling the `createJob` mutation:
```javascript
// src/graphql/resolvers/jobResolvers.js
export const jobResolvers = {
  Query: {
    jobs: async (_, __, { dataSources }) => {
      return await dataSources.jobsAPI.getAllJobs();
    },
  },
  Mutation: {
    createJob: async (_, { input }, { dataSources, token }) => {
      if (!token) {
        throw new Error('Authentication required');
      }
      return await dataSources.jobsAPI.createJob(input);
    },
  },
};
```
1. Update the `src/index.js` file to pass the token from the request headers to the `context`:
```javascript
// src/index.js
import { ApolloServer } from 'apollo-server-express';
import express from 'express';
import { typeDefs, resolvers } from './graphql/index.js';
import JobsAPI from './dataProvider.js';

const app = express();
const server = new ApolloServer({
  typeDefs,
  resolvers,
  dataSources: () => ({
    jobsAPI: new JobsAPI(),
  }),
  context: ({ req }) => {
    // Get the token from the request headers
    const token = req.headers.authorization || '';
    return { token };
  },
});

// ...rest of the code
```
Now, the `createJob` mutation is protected and requires authentication. To call this mutation, you'll need to pass a valid token in the `Authorization` header of your request:
```bash
Authorization: Bearer <your_token>
```
Replace `<your_token>` with a valid token for your REST API. If the token is not provided or invalid, the `createJob` mutation will return an error.

You can indeed use Express's global error handling middleware to handle errors more effectively. To do this, follow these steps:

1. Create a custom error class to handle GraphQL errors:
```javascript
// src/error.js
class GraphQLError extends Error {
  constructor(message, statusCode) {
    super(message);
    this.statusCode = statusCode;
    this.isGraphQLError = true;
  }
}
export default GraphQLError;
```
1. Update the `src/graphql/resolvers/jobResolvers.js` file to use the custom error class:
```javascript
// src/graphql/resolvers/jobResolvers.js
import GraphQLError from '../error.js';

export const jobResolvers = {
  Query: {
    jobs: async (_, __, { dataSources }) => {
      return await dataSources.jobsAPI.getAllJobs();
    },
  },
  Mutation: {
    createJob: async (_, { input }, { dataSources, token }) => {
      if (!token) {
        throw new GraphQLError('Authentication required', 401);
      }
      return await dataSources.jobsAPI.createJob(input);
    },
  },
};
```
1. Update the `src/index.js` file to include the global error handling middleware:
```javascript
// src/index.js
import { ApolloServer } from 'apollo-server-express';
import express from 'express';
import { typeDefs, resolvers } from './graphql/index.js';
import JobsAPI from './dataProvider.js';
import GraphQLError from './error.js';

const app = express();
const server = new ApolloServer({
  typeDefs,
  resolvers,
  dataSources: () => ({
    jobsAPI: new JobsAPI(),
  }),
  context: ({ req }) => {
    const token = req.headers.authorization || '';
    return { token };
  },
});

// Apply the GraphQL middleware
server.applyMiddleware({ app });

// Add the global error handling middleware
app.use((err, req, res, next) => {
  if (err.isGraphQLError) {
    res.status(err.statusCode || 500).json({
      error: {
        message: err.message,
        statusCode: err.statusCode,
      },
    });
  } else {
    res.status(500).json({ error: { message: 'Internal server error', statusCode: 500 } });
  }
});

app.listen({ port: 4000 }, () =>
  console.log(`🚀 Server ready at http://localhost:4000${server.graphqlPath}`)
);
```
Now, if an error occurs in your GraphQL resolvers, it will be caught by the global error handling middleware. This will ensure that the errors are returned with the appropriate status code and a consistent error message structure.

