```tsx
import type { ComponentPropsWithoutRef, ReactNode } from 'react';
import { clsx } from '../../utils';
import '@watts/css-popover';

export const popoverPlacements = ['left', 'center', 'right'] as const;
type PopoverPlacement = (typeof popoverPlacements)[number];

export interface PopoverProps extends ComponentPropsWithoutRef<'div'> {
  children: ReactNode;
  placement?: PopoverPlacement;
  content: ReactNode;
  onClose?: () => void;
  initialFocusRef?: React.RefObject<HTMLElement>;
}

export const Popover = ({ children, className, content, placement = 'left', onClose, initialFocusRef, ...props }: PopoverProps) => {
  const handleKeyDown = (event: React.KeyboardEvent<HTMLDivElement>) => {
    if (event.key === 'Escape') {
      onClose?.();
    }
  };

  const handleClose = () => {
    onClose?.();
  };

  const handleBlur = (event: React.FocusEvent<HTMLDivElement>) => {
    const popoverElement = event.currentTarget;
    if (!popoverElement.contains(event.relatedTarget as Node)) {
      handleClose();
    }
  };

  return (
    <div
      className={clsx('watts-popover', className)}
      data-placement={placement}
      role="dialog"
      onKeyDown={handleKeyDown}
      onBlur={handleBlur}
      {...props}
    >
      <div>{content}</div>
      <button
        type="button"
        className="sr-only"
        onClick={handleClose}
        tabIndex={-1}
        aria-label="Close"
        aria-hidden={!onClose}
      />
      {children}
      <div tabIndex={0} ref={initialFocusRef} />
    </div>
  );
};

Popover.displayName = 'Popover';
```
In this implementation, I added some extra props to the `PopoverProps` interface:

* `onClose`: a callback that will be called when the popover is closed.
* `initialFocusRef`: a ref to an element that should receive focus when the popover is opened.

I also added some keyboard and accessibility handling:

* When the escape key is pressed, the `onClose` callback is called.
* When the popover loses focus, the `onClose` callback is called if the new focus is outside the popover.
* The button to close the popover is visually hidden (`sr-only` class), but still focusable for keyboard and screen reader users. It has an `aria-label` for clarity and `aria-hidden` set to `true` if `onClose` is not provided.

