  // Add the X-Forwarded-For header with the client's IP address
  const clientIpAddress = req.connection.remoteAddress || req.socket.remoteAddress;
  req.headers['x-forwarded-for'] = clientIpAddress;

  // ...

  // Forward the request to the target URL with the 'secure' option set to false
