package main

import (
    "context"
    "fmt"
    "os"

    "github.com/go-acme/lego/v4"
    "github.com/go-acme/lego/v4/challenge"
    "github.com/go-acme/lego/v4/providers/dns/googlecloud"
)

func main() {
    // Replace with your credentials file path
    credentialFile := "path/to/credentials.yaml"

    // Create a new Google Domains solver
    providers, err := NewGoogleDomainsSolver(credentialFile)
    if err != nil {
        fmt.Printf("Error creating Google Domains solver: %v", err)
        os.Exit(1)
    }

    // Create a new Lego client
    config := lego.NewConfig()
    config.CADirURL = "https://acme-staging-v02.api.letsencrypt.org/directory"
    client, err := lego.NewClient(config)
    if err != nil {
        fmt.Printf("Error creating Lego client: %v", err)
        os.Exit(1)
    }

    // Register the Google Domains solver with the Lego client
    for _, provider := range providers {
        err = client.Challenge.SetDNS01Provider(provider)
        if err != nil {
            fmt.Printf("Error setting DNS01 provider: %v", err)
            os.Exit(1)
        }
    }

    // Replace with your domain names
    domains := []string{
        "example.com",
        "*.example.com",
    }

    // Request a certificate
    request := lego.NewCertificateRequest(domains)
    request.CSR, err = lego.GenerateCSR(request.Key, nil)
    if err != nil {
        fmt.Printf("Error generating CSR: %v", err)
        os.Exit(1)
    }

    err = client.Challenge.SetHTTP01Provider(nil)
    if err != nil {
        fmt.Printf("Error setting HTTP01 provider: %v", err)
        os.Exit(1)
    }

    err = client.Challenge.SetTLSALPN01Provider(nil)
    if err != nil {
        fmt.Printf("Error setting TLSALPN01 provider: %v", err)
        os.Exit(1)
    }

    _, err = client.Certificate.Obtain(request)
    if err != nil {
        fmt.Printf("Error obtaining certificate: %v", err)
        os.Exit(1)
    }

    fmt.Println("Certificate obtained successfully")
}
