        DNS01Solver: &googlecloud.ProviderSolver{
            Provider: provider,
        },
    }

    // Register the solver with lego
    err = challenge.RegisterSolver(strings.Join(cred.Domains, ","), solver)
    if err != nil {
        panic(err)
    }

