```python
import numpy as np
from scipy.optimize import linprog

# Define intersection topology as a graph
intersection_topology = {
    'signal_1': {
        'next_signal': 'signal_2',
        'road_segment': 'segment_1'
    },
    'signal_2': {
        'next_signal': 'signal_3',
        'road_segment': 'segment_2'
    },
    'signal_3': {
        'next_signal': 'signal_4',
        'road_segment': 'segment_3'
    },
    'signal_4': {
        'next_signal': 'signal_1',
        'road_segment': 'segment_4'
    }
}

# Collect traffic data
traffic_data = {
    'signal_1': {
        'flow': 100,
        'waiting_time': 10
    },
    'signal_2': {
        'flow': 120,
        'waiting_time': 8
    },
    'signal_3': {
        'flow': 80,
        'waiting_time': 12
    },
    'signal_4': {
        'flow': 90,
        'waiting_time': 9
    }
}

# Define optimization variables and constraints
green_times = np.zeros(len(intersection_topology))
min_green_times = np.array([30, 30, 30, 30])
max_cycle_time = 120
segment_capacities = np.array([200, 200, 200, 200])
A_eq = np.ones((1, len(intersection_topology)))
b_eq = np.array([max_cycle_time])

# Define objective function to minimize total delay
def objective_function(green_times):
    total_delay = 0
    for signal in intersection_topology:
        next_signal = intersection_topology[signal]['next_signal']
        road_segment = intersection_topology[signal]['road_segment']
        flow = traffic_data[signal]['flow']
        waiting_time = traffic_data[signal]['waiting_time']
        green_time = green_times[list(intersection_topology.keys()).index(signal)]
        segment_capacity = segment_capacities[list(intersection_topology.keys()).index(signal)]
        segment_flow = flow * green_time / max_cycle_time
        if segment_flow > segment_capacity:
            segment_flow = segment_capacity
        segment_delay = (1 - segment_flow / segment_capacity) * waiting_time
        total_delay += segment_delay
    return total_delay

# Solve the optimization problem
result = linprog(c=objective_function, A_eq=A_eq, b_eq=b_eq, bounds=[(min_green_time, None) for min_green_time in min_green_times], method='simplex')
green_times = result.x

# Update traffic signals with new green times
for signal in intersection_topology:
    green_time = green_times[list(intersection_topology.keys()).index(signal)]
    print(f'Signal {signal} - Green time: {green_time}')
```
