import { motion, useAnimation } from "framer-motion";

const TextAnimate = () => {
  const text = "Hello World!";

  return (
    <motion.div
      style={{ display: "flex", justifyContent: "center" }}
    >
      {text.split("").map((letter, index) => (
        <motion.div
          key={index}
          variants={{
            start: { y: 0, transition: { duration: 0.5, ease: "easeOut" } },
            end: { y: -20, transition: { duration: 0.5, ease: "easeIn" } },
          }}
