        </motion.div>
      ))}
    </motion.div>
  );
};
```
In this example, we define two variants "start" and "end", which represent the start and end positions of the bounce animation. The "animate" property is used to animate between these two variants with a looping transition that repeats indefinitely, with a repeat delay of 1 second.

To trigger an animation only when the element is visible on the screen, you can use the "onViewportBoxUpdate" callback in Frame-motion. This callback is called every time the layout of the element changes, and it provides information about the element's position relative to the viewport.

Here's an example of how you can trigger an animation when the element is visible on the screen:
```javascript
import { motion, useViewportScroll, useTransform } from "framer-motion";

const TextAnimate = () => {
  const text = "Hello World!";
  const { scrollYProgress } = useViewportScroll();
  const yRange = useTransform(scrollYProgress, [0, 1], [0, 1]);

  return (
    <motion.div
      style={{ display: "flex", justifyContent: "center" }}
      onViewportBoxUpdate={(info, delta) => {
        if (info.isVisible) {
          yRange.set(1);
        }
      }}
    >
      {text.split("").map((letter, index) => (
        <motion.div
          key={index}
          animate={{
            y: yRange.interpolate({
              range: [0, 1],
              output: [-100, 0],
            }),
          }}
        >
          {letter === " " ? "\u00a0" : letter}
        </motion.div>
      ))}
    </motion.div>
  );
};
```
In this example, we use the `useViewportScroll` hook to get the current scroll position, and the `useTransform` hook to map the scroll position to a range of values between 0 and 1. The `onViewportBoxUpdate` callback is used to set the value of the `yRange` when the element is visible on the screen. Finally, the animation is triggered using the `animate` property, and the final Y position is determined by interpolating the value of `yRange`.

