#define CONNECTED_COMPONENTS_CHECKER_H

#include "clang/StaticAnalyzer/Core/BugReporter/BugType.h"
#include "clang/StaticAnalyzer/Core/Checker.h"
#include "clang/StaticAnalyzer/Core/PathSensitive/AnalysisManager.h"

namespace clang {
namespace ento {

class ConnectedComponentsChecker
    : public Checker<check::ASTCodeBody> {
public:
  void checkASTCodeBody(const Decl *D, AnalysisManager &Mgr,
                        BugReporter &BR) const;
};

} // namespace ento
} // namespace clang

#endif // CONNECTED_COMPONENTS_CHECKER_H
```
Next, create a source file named "ConnectedComponentsChecker.cpp":
```cpp
// ConnectedComponentsChecker.cpp
#include "ConnectedComponentsChecker.h"
#include "clang/Analysis/CFG.h"
#include "clang/StaticAnalyzer/Core/CheckerRegistry.h"

using namespace clang;
using namespace ento;

namespace {
void visitCFGBlock(const CFGBlock *Block, std::set<const CFGBlock *> &Visited) {
  if (!Block || Visited.count(Block))
    return;

  Visited.insert(Block);
  for (const auto &Succ : Block->succs())
    visitCFGBlock(Succ.getReachableBlock(), Visited);
}
} // namespace

void ConnectedComponentsChecker::checkASTCodeBody(const Decl *D,
                                                  AnalysisManager &Mgr,
                                                  BugReporter &BR) const {
  const auto *FD = dyn_cast<FunctionDecl>(D);
  if (!FD)
    return;

  std::unique_ptr<CFG> FuncCFG = CFG::buildCFG(
      FD, FD->getBody(), &FD->getASTContext(), CFG::BuildOptions());
  if (!FuncCFG)
    return;

  int ConnectedComponents = 0;
  std::set<const CFGBlock *> Visited;
  for (const CFGBlock &Block : *FuncCFG) {
    if (Visited.count(&Block) == 0) {
      ConnectedComponents++;
      visitCFGBlock(&Block, Visited);
    }
  }

  // Use 'ConnectedComponents' to report a bug, store it for further analysis,
  // or print it to the console.
  llvm::errs() << "Number of connected components: " << ConnectedComponents
               << "\n";
}

// Register the checker with the Clang Static Analyzer.
extern "C" void clang_registerCheckers(CheckerRegistry &Registry) {
  Registry.addChecker<ConnectedComponentsChecker>(
      "example.ConnectedComponents",
      "Computes the number of connected components in the CFG");
}
```
