  "Shark Attack - Grouplove",
  "Silvertongue - Young the Giant",
  "Electric - Alina Baraz feat. Khalid",
  "The Less I Know The Better - Tame Impala",
  "Something to Believe In - Young the Giant",
  "Youth - Glass Animals",
  "Black Mambo - Glass Animals",
  "Helena Beat - Foster the People",
  "Some Nights - fun.",
  "Tongue Tied - Grouplove"
];

// Define your Spotify access token
const accessToken = 'YOUR_ACCESS_TOKEN';

// Define the user ID of the Spotify account you want to create the playlist for
const userId = 'YOUR_USER_ID';

// Search for each song and retrieve its Spotify track ID
const searchAndAddTracks = async () => {
  const trackIds = [];
  for (const song of songs) {
    const [name, artist] = song.split(' - ');
    const query = `track:${name} artist:${artist}`;
    const searchUrl = `https://api.spotify.com/v1/search?q=${encodeURIComponent(query)}&type=track&limit=1`;
    const response = await fetch(searchUrl, {
      headers: {
        'Authorization': `Bearer ${accessToken}`
      }
    });
    const data = await response.json();
    const trackId = data.tracks.items[0].id;
    trackIds.push(`spotify:track:${trackId}`);
  }
  return trackIds;
}

// Create a new playlist and add the tracks to it
const createPlaylist = async () => {
  const trackIds = await searchAndAddTracks();
  const createUrl = `https://api.spotify.com/v1/users/${userId}/playlists`;
  const response = await fetch(createUrl, {
    method: 'POST',
    headers: {
