      name: 'Midnight Drive',
      description: 'A playlist for late-night drives with a mix of indie, rock, and electronic vibes.',
      public: true,
      tracks: trackIds.map(id => ({ uri: id }))
    })
  });
  const data = await response.json();
  console.log(`Created new playlist with ID ${data.id}`);
}

createPlaylist();
