In TypeScript, you can get the URL parameters from a query string using the `URLSearchParams` API. Here's an example function that parses a query string and returns an object with the key-value pairs of the parameters:
```typescript
function getUrlParams(queryString: string): Record<string, string> {
  const searchParams = new URLSearchParams(queryString);
  const params: Record<string, string> = {};

  for (const [key, value] of searchParams.entries()) {
    params[key] = value;
  }

  return params;
}
```
You can use this function as follows:
```typescript
const queryString = "?name=John&age=30";
const params = getUrlParams(queryString);
console.log(params); // { name: "John", age: "30" }
```
Note that this function assumes that the query string is already URL-encoded. If you need to encode the query string yourself, you can use the `encodeURIComponent()` function:
```typescript
const name = "John Doe";
const age = 30;
const queryString = `?name=${encodeURIComponent(name)}&age=${encodeURIComponent(age.toString())}`;
const params = getUrlParams(queryString);
console.log(params); // { name: "John Doe", age: "30" }
```

If `URLSearchParams` is not available in your React Native environment, you can still parse the query string using the `split()` and `reduce()` methods. Here's an example function that does this:
```typescript
function getUrlParams(queryString: string): Record<string, string> {
  const params: Record<string, string> = {};

  queryString
    .slice(1) // Remove the '?' character from the beginning of the query string
    .split('&') // Split the query string into an array of key-value pairs
    .reduce((prev, current) => {
      const [key, value] = current.split('=');
      prev[key] = decodeURIComponent(value);
      return prev;
    }, params);

  return params;
}
