import java.io.File
import java.io.FileInputStream
import java.math.BigInteger
import javax.imageio.ImageIO

fun aHash(file: File): BigInteger {
    val image = ImageIO.read(FileInputStream(file))
    val resized = image.getScaledInstance(8, 8, Image.SCALE_DEFAULT)
    val pixels = IntArray(64)

    if (resized is BufferedImage) {
        for (y in 0 until 8) {
            for (x in 0 until 8) {
                val pixel = resized.getRGB(x, y)
                val gray = (pixel and 0xFF) + ((pixel shr 8) and 0xFF) + ((pixel shr 16) and 0xFF)
                pixels[y * 8 + x] = gray / 3
            }
        }
    }

    var result = BigInteger.ZERO

    for (i in pixels.indices) {
        if (pixels[i] >= pixels[pixels.size / 2]) {
            result = result.or(BigInteger.ONE.shiftLeft(i))
        }
    }

    return result
}

fun main() {
    val file1 = File("image1.png")
    val file2 = File("image2.png")

    val hash1 = aHash(file1)
    val hash2 = aHash(file2)

    if (hash1 == hash2) {
        println("The images are the same.")
    } else {
        println("The images are different.")
    }
}
