    val hash1 = getHash(resized1, avgPixelValue1)
    val hash2 = getHash(resized2, avgPixelValue2)

    // Calculate the Hamming distance between the two hash values
    return hammingDistance(hash1, hash2)
}

fun getAveragePixelValue(image: BufferedImage): Int {
    var totalPixelValue = 0

    for (x in 0 until image.width) {
        for (y in 0 until image.height) {
            totalPixelValue += image.getRGB(x, y)
        }
    }

    return totalPixelValue / (image.width * image.height)
}

fun getHash(image: BufferedImage, avgPixelValue: Int): Long {
    var hash = 0L

    for (x in 0 until image.width) {
        for (y in 0 until image.height) {
            val pixelValue = image.getRGB(x, y)

            if (pixelValue >= avgPixelValue) {
                hash = hash or (1L shl (x * 8 + y))
            }
        }
    }

    return hash
}

fun hammingDistance(hash1: Long, hash2: Long): Int {
    var distance = 0

    for (i in 0 until 64) {
        val bit1 = hash1 shr i and 1
        val bit2 = hash2 shr i and 1

        if (bit1 != bit2) {
            distance++
        }
    }

    return distance
}
```
