export async function joinGame(gameId, user) {
  try {
    const player = userToPlayer(user);
    const gameRef = doc(db, 'games', gameId);
    const gameSnapshot = await getDoc(gameRef);

    if (!gameSnapshot.exists()) {
      console.log('No such game exists!');
      return;
    }

    const gameData = gameSnapshot.data();
    if (gameData.status !== 'waiting') {
      console.log('Cannot join the game: the game has already started.');
      return;
    }

    // Check if the user is already in the game
    const playerRef = doc(collection(gameRef, 'players'), player.id);
    const playerSnapshot = await getDoc(playerRef);
    if (playerSnapshot.exists()) {
      console.log('The user is already in the game.');
      return;
    }

    // Add the user to the 'players' subcollection
    await setDoc(playerRef, player);
    console.log('User joined the game successfully.');
  } catch (e) {
    console.error('Error joining the game:', e);
  }
}
